#include <vector>
#include <numeric>
#include <algorithm>

using namespace std;

class Solution {
public:
    long long maxScore(vector<int>& nums) {
        long long total = accumulate(nums.begin(), nums.end(), 0LL);
        int n = nums.size();
        if (n % 2 != 0) {
            int mn = *min_element(nums.begin(), nums.end());
            return total - mn;
        }

        long long minPair = (long long)nums[0] + nums[1];
        for (int i = 1; i < n - 1; ++i) {
            minPair = min(minPair, (long long)nums[i] + nums[i + 1]);
        }
        return total - minPair;
    }
};

class Solution {
    public long maxScore(int[] nums) {
        long total = 0;
        int n = nums.length;
        for (int x : nums) total += x;

        if (n % 2 != 0) {
            int mn = nums[0];
            for (int x : nums) mn = Math.min(mn, x);
            return total - mn;
        }

        long minPair = (long) nums[0] + nums[1];
        for (int i = 1; i < n - 1; i++) {
            minPair = Math.min(minPair, (long) nums[i] + nums[i + 1]);
        }
        return total - minPair;
    }
}

var maxScore = function(nums) {
    const total = nums.reduce((acc, x) => acc + BigInt(x), 0n);
    const n = nums.length;

    if (n % 2 !== 0) {
        let mn = nums[0];
        for (const x of nums) {
            if (x < mn) mn = x;
        }
        return Number(total - BigInt(mn));
    }

    let minPair = BigInt(nums[0]) + BigInt(nums[1]);
    for (let i = 1; i < n - 1; i++) {
        const pairSum = BigInt(nums[i]) + BigInt(nums[i + 1]);
        if (pairSum < minPair) minPair = pairSum;
    }
    return Number(total - minPair);
};
